#!/usr/bin/env bash

# Usage: ./copysql.bash source_directory destination_directory
# copy sql files from the source directory to the destination directory, renaming them as
# original_file_copy.sql
set -ueo pipefail # -u: fail on unset variable, -e: fail on error, -o pipefail: fail on error in a pipeline

if [ "$#" -ne 2 ]; then
	echo "Usage: $0 source_directory destination_directory"
	exit 1
fi
SRC=$(realpath "$1")
DST=$(realpath "$2")

# move files in the form of original_file.sql to original_file_copy.sql
# with an added header in the form
# -- AUTOGENERATED: DO NOT EDIT
# -- SOURCE: source_file.sql on date
for file in \
	"$SRC/schema.sql" \
    ; do
	if [ -f "$file" ]; then
		filename=$(basename "$file")
		# create a new file with the header
		echo "--AUTOGENERATED: DO NOT EDIT" >"$DST/${filename%.sql}_copy.sql"
		# add the content of the original file to the new file
		cat "$file" >>"$DST/${filename%.sql}_copy.sql"

		# tell the user about it, mimicking the format of `cp -v`.
		echo "$file --> $DST/${filename%.sql}_copy.sql"

	else
		echo "No SQL files found in $SOURCE_DIR"
		exit 1
	fi
done